1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	import java.util.Map;
7	import java.util.HashMap;
8	import java.util.Set;
9	import java.util.HashSet;
10	
11	/**
12	 * A simple predator-prey simulator, based on a rectangular field
13	 * containing actors, or animals and plants.
14	 *
15	 * @version 27.02.22
16	 */
17	public class Simulator
18	{
19	    // Constants representing configuration information for the simulation.
20	    // The default width for the grid.
21	    private static final int DEFAULT_WIDTH = 250;
22	    // The default depth of the grid.
23	    private static final int DEFAULT_DEPTH = 250;
24	    // List of actors in the field.
25	    private List<Actor> actors;
26	    // The probabilities that actors will be created in any given grid position.
27	    private Map<Actor,Double> actorCreationProb; 
28	    // List of diseases in the simulation.
29	    public static final List<Disease> diseases = createDiseases();
30	    // The current state of the field.
31	    private Field field;
32	    // The current step of the simulation.
33	    private int step;
34	    // A graphical view of the simulation.
35	    private SimulatorView view;
36	    // The current time in the field.
37	    private Time time;
38	    // The current weather condition of the field.
39	    private WeatherCond weatherCond;
40	
41	    /**
42	     * Construct a simulation field with default size.
43	     */
44	    public Simulator()
45	    {
46	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
47	    }
48	
49	    /**
50	     * Create a simulation field with the given size.
51	     * @param depth Depth of the field. Must be greater than zero.
52	     * @param width Width of the field. Must be greater than zero.
53	     */
54	    public Simulator(int depth, int width)
55	    {
56	        if(width <= 0 || depth <= 0) {
57	            System.out.println("The dimensions must be greater than zero.");
58	            System.out.println("Using default values.");
59	            depth = DEFAULT_DEPTH;
60	            width = DEFAULT_WIDTH;
61	        }
62	
63	        actors = new ArrayList<>();
64	        field = new Field(depth, width);
65	        time = new Time(3);
66	        actorCreationProb = createActorCreationProb();
67	        weatherCond = WeatherCond.Sunny; //Sunny weather is default 
68	
69	        // Create a view of the state of each location in the field.
70	        view = new SimulatorView(depth, width);
71	        view.setColor(Lemur.class, Color.RED.darker());
72	        view.setColor(Panther.class, Color.ORANGE);
73	        view.setColor(Grass.class, Color.GREEN.darker());
74	        view.setColor(Water_Fern.class, Color.GREEN.brighter());
75	        view.setColor(Alligator.class, Color.LIGHT_GRAY);
76	        view.setColor(Salamander.class, Color.MAGENTA);
77	        view.setColor(Catfish.class, Color.BLACK);
78	
79	        
80	        weatherCond.setTime(time);
81	        // Setup a valid starting point.
82	        reset();
83	    }
84	
85	    /**
86	     * Create a Map with a key of an Actor object, one of each subclass of Animal and Plant,
87	     * and a value of the creation proability.
88	     * @return The actor creation prbability Map.
89	     */
90	    private Map<Actor,Double> createActorCreationProb()
91	    {
92	        Map<Actor,Double> tempMap = new HashMap<>();
93	        Location location = new Location(0, 0);
94	        tempMap.put(new Grass(time, field, location),0.8);
95	        tempMap.put(new Water_Fern(time, field, location),0.9);
96	        tempMap.put(new Salamander(time, field, location),0.5);
97	        tempMap.put(new Catfish(time, field, location),0.7);
98	        tempMap.put(new Lemur(time, field, location),0.45);
99	        tempMap.put(new Panther(time, field, location),0.3);
100	        tempMap.put(new Alligator(time, field, location),0.25);
101	        
102	        
103	        return tempMap;
104	    }
105	
106	    /**
107	     * Create a List of all the diseases in the simulation, specify which actors start with the disease and which actors can catch the disease.
108	     * Starting and affected actors are specified by a Map with a String key and double value, of probability to get disease for starting actors,
109	     * and disease severity for affected actors. Severity ranges from 0.0 to 1.0, 0.0 being completely fatal as soon as contracted, and 1.0 meaning
110	     * the actor is just a disease carrier.
111	     * @return The diseases List.
112	     */
113	    private static List<Disease> createDiseases()
114	    {
115	        List<Disease> list = new ArrayList<>();
116	        Disease dengue = new Disease("dengue", true, true);
117	
118	        dengue.getActorsAffectedMap().put("Lemur",0.9);
119	        dengue.getActorsAffectedMap().put("Panther",0.6);
120	        dengue.getActorsAffectedMap().put("Alligator",0.6);
121	
122	        dengue.getStartingActorsMap().put("Lemur",0.4);
123	        list.add(dengue);
124	        
125	        Disease river_fever = new Disease("river_fever", true, false);
126	
127	        river_fever.getActorsAffectedMap().put("Water_Fern",1.0);
128	        river_fever.getActorsAffectedMap().put("Catfish",0.7);
129	        river_fever.getActorsAffectedMap().put("Salamander",0.8);
130	
131	        river_fever.getStartingActorsMap().put("Water_Fern",0.4);
132	        list.add(river_fever);
133	        
134	        return list;
135	    }
136	
137	    /**
138	     * Run the simulation from its current state for a reasonably long period,
139	     * (4000 steps).
140	     */
141	    public void runLongSimulation()
142	    {
143	        simulate(4000);
144	    }
145	
146	    /**
147	     * Run the simulation from its current state for the given number of steps.
148	     * Stop before the given number of steps if it ceases to be viable.
149	     * @param numSteps The number of steps to run for.
150	     */
151	    public void simulate(int numSteps)
152	    {
153	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
154	            simulateOneStep();
155	            delay(60);   // uncomment this to run more slowly
156	        }
157	    }
158	
159	    /**
160	     * Run the simulation from its current state for a single step.
161	     * Iterate over the whole field updating the state of each actor.
162	     */
163	    public void simulateOneStep()
164	    {
165	        step++;
166	        time.incrementTime(); 
167	        weatherCond = weatherCond.nextCondition();
168	        // Provide space for newborn actors.
169	
170	        List<Actor> newActors = new ArrayList<>();        
171	        // Let all actors act.
172	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
173	            Actor actor = it.next();
174	            actor.act(newActors, weatherCond);
175	            if(! actor.isAlive()) {
176	                it.remove();
177	            }
178	        }
179	
180	        // Add the newly born actors to the main lists.
181	        actors.addAll(newActors);
182	
183	        view.showStatus(step, field, weatherCond, diseases);
184	        field.setWeatherField(weatherCond);
185	    }
186	
187	    /**
188	     * Reset the simulation to a starting position.
189	     */
190	    public void reset()
191	    {
192	        step = 0;
193	        actors.clear();
194	        populate();
195	
196	        // Show the starting state in the view.
197	        view.showStatus(step, field, weatherCond, diseases);
198	    }
199	
200	    /**
201	     * Randomly populate the field with actors.
202	     * Actors can only populate areas they will survive in
203	     * i.e. actors that will not survive in water cannot be placed there.
204	     */
205	    private void populate()
206	    {
207	        Random rand = Randomizer.getRandom();
208	        field.clear();
209	        for(int row = 0; row < field.getDepth(); row++) {
210	            for(int col = 0; col < field.getWidth(); col++) {
211	                for (Actor actor : actorCreationProb.keySet()){
212	                    Location location = new Location(row, col);
213	                    if((rand.nextDouble() <= actorCreationProb.get(actor)) && ((actor.canMoveOnLand() && actor.canMoveOnWater()) || (field.isUnderWater(location.getRow(), location.getCol()) && actor.canMoveOnWater()) || (!field.isUnderWater(location.getRow(), location.getCol()) && actor.canMoveOnLand()))) {
214	                        Actor newActor = actor.birth(new Location(row, col));
215	                        actors.add(newActor);
216	                        break;
217	                    }
218	                }
219	            }
220	        }
221	    }
222	
223	    /**
224	     * Pause for a given time.
225	     * @param millisec  The time to pause for, in milliseconds
226	     */
227	    private void delay(int millisec)
228	    {
229	        try {
230	            Thread.sleep(millisec);
231	        }
232	        catch (InterruptedException ie) {
233	            // wake up
234	        }
235	    }
236	}
