6	/**
7	 * A class representing shared characteristics of animals.
8	 *
9	 * @version 27.02.22
10	 */
11	public abstract class Animal extends Actor
12	{
13	    protected int foodLevel;
14	    protected boolean female;
15	    protected boolean nocturnal;
16	
17	    /**
18	     * Create a new animal at location in field with time as well.
19	     * With a set that will add any disease that it catches
20	     * 
21	     * @param field The field currently occupied.
22	     * @param location The location within the field.
23	     * @param time The time in the simulation
24	     */
25	    public Animal(Time time, Field field, Location location)
26	    {
27	        super(time, field, location);
28	
29	    }
30	
31	    /**
32	     * Make this animal act - that is: make it do
33	     * whatever it wants/needs to do.
34	     * Checks if the time of day matches if the animal is nocturnal or not,
35	     * then attempts to find food and move.
36	     * @param newAnimals A list to receive newly born animals.
37	     * @param weather The weather condition of the simulation.
38	     */
39	    public void act(List<Actor> newAnimals, WeatherCond weather)
40	    {
41	        super.act(newAnimals,weather);
42	        incrementHunger();
43	        if(isAlive()&&(getTime().isDay() != nocturnal)) {
44	            giveBirth(newAnimals);            
45	            // Move towards a source of food if found.
46	            Location newLocation = null;
47	            if (getField().getWeatherAttributeValueAt("visibility", getLocation()) > 0.4){
48	                newLocation = findFood();
49	            }
50	            if(newLocation == null) { 
51	                // No food found - try to move to a free location.
52	                newLocation = getField().freeAdjacentLocation(this, getLocation());
53	            }
54	            // See if it was possible to move.
55	            if(newLocation != null) {
56	                setLocation(newLocation);
57	            }
58	            else {
59	                // Overcrowding.
60	                setDead();
61	            }
62	        }
63	    }
64	
65	    /**
66	     * Make this animal more hungry. This could result in the animal's death.
67	     */
68	    private void incrementHunger()
69	    {
70	        foodLevel--;
71	        if(foodLevel <= 0) {
72	            setDead();
73	        }
74	    }
75	
76	    /**
77	     * Checks if the animal is female and looks for a mate
78	     * @param newAnimals The List of new animals that have been born to add to the simulator List of actors
79	     */
80	    protected void giveBirth(List<Actor> newAnimals)
81	    {
82	        // New animals are born into adjacent locations.
83	        // Get a list of adjacent free locations.
84	        if (female&&findMate()) {
85	            super.giveBirth(newAnimals);
86	        }
87	    }
88	
89	    /**
90	     * Searches for a mate to breed with.
91	     * Searches first for an adjacent animal of the same dynamic type,
92	     * then if that animal is male.
93	     * @return true if a mate is found.
94	     */
95	    protected boolean findMate()
96	    {
97	        Field field = getField();
98	        List<Location> adjacent = field.adjacentLocations(getLocation());
99	        Iterator<Location> it = adjacent.iterator();
100	        while(it.hasNext()){
101	            Location where = it.next();
102	            Object actor = field.getObjectAt(where);
103	            if (actor instanceof Animal) {
104	                Animal animal = (Animal) actor;
105	                if (animal.getActorName().equals(getActorName())&& !animal.female){
106	                    giveDiseases(animal);
107	                    return true;
108	                }
109	            }
110	        }
111	        return false;
112	    }
113	
114	    /**
115	     * Transfer diseases from the male mate to the female and vice versa.
116	     * @param mate The male mate that the female breeds with.
117	     */
118	    protected void giveDiseases(Animal mate)
119	    {
120	        for (Disease disease: mate.setDiseases){
121	            if (disease.isSpreadByBirth()){
122	                setDiseases.add(disease);
123	            }
124	        }
125	        for (Disease disease: setDiseases){
126	            if (disease.isSpreadByBirth()){
127	                mate.getActorDiseaseSet().add(disease);
128	            }
129	        }
130	    }
131	
132	    /**
133	     * Look for rabbits adjacent to the current location.
134	     * Only the first live rabbit is eaten.
135	     * @return Where food was found, or null if it wasn't.
136	     */
137	    protected Location findFood()
138	    {
139	        Field field = getField();
140	        List<Location> adjacent = field.adjacentLocations(getLocation());
141	        Iterator<Location> it = adjacent.iterator();
142	        while(it.hasNext()) {
143	            Location where = it.next();
144	            if ((canMoveOnLand() && canMoveOnWater()) || (field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnWater()) || (!field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnLand())) {
145	                Object actor = field.getObjectAt(where);
146	                if (actor instanceof Actor) {
147	                    Actor prey = (Actor) actor;
148	                    for(String actorName : getPreyFoodValuesMap().keySet()) {
149	                        if(getPreyFoodValuesMap().containsKey(prey.getActorName()) && prey.isAlive()) {
150	                            for (Disease disease: prey.setDiseases){
151	                                if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getActorName())){
152	                                    setDiseases.add(disease);
153	                                }
154	                            }
155	                            prey.setDead();
156	                            if (foodLevel + getPreyFoodValuesMap().get(prey.getActorName()) < getMaxFood()) {
157	                                foodLevel += getPreyFoodValuesMap().get(prey.getActorName());
158	                            }
159	                            else {
160	                                foodLevel = getMaxFood();
161	                            }
162	                            return where;
163	                        }
164	                    }
165	                }
166	            }
167	        }
168	        return null;
169	    }
170	
171	    /**
172	     * Returns how many animals are produced during birth
173	     * @return The number of animals birthed
174	     */
175	    abstract protected int breed();
176	
177	    /**
178	     * Creates a new animal 
179	     * @param location The new location of the child
180	     * @param Set<Disease> The diseases that the parent had is passed down
181	     * @return The new animal created
182	     */
183	    abstract protected Animal birth(Location loc, Set<Disease>... parentDiseases);
184	
185	    /**
186	     * Returns the Map of the prey of the animal and how much food they provide it
187	     * @return The Map of the prey of the animal and how much food they provide it
188	     */
189	    abstract protected Map<String, Integer> getPreyFoodValuesMap();
190	
191	    /**
192	     * Returns the max food value that the animal can have
193	     * @return The max food value that the animal can have
194	     */
195	    abstract protected int getMaxFood();
196	}

