1	import java.util.List;
2	import java.util.ArrayList;
3	import java.util.Random;
4	import java.util.HashMap;
5	import java.util.Map;
6	/**
7	 * The different weather that can occur randomly in the simulator, they all have different attributes which
8	 * affect the animals and plants in the simulator
9	 *
10	 * @version 27.02.22
11	 */
12	public enum WeatherCond
13	{
14	    Rain (0.6 ,0.5,0.8),
15	    Fog (0.2,0.5,0.5),
16	    Sunny (1,1,-0.5),
17	    Cloudy (0.5,0.5,0.4),
18	    Windy (0.7,0.5,0.3),
19	    Storm (0.4,0.5,1);
20	
21	    private static final Random rand = Randomizer.getRandom();
22	    private Map<String, Double> weatherAttributes; 
23	    private static Time timeOfDay;
24	
25	    /**
26	     * Puts attributes of each weather condition in a Map.
27	     * @param visibility The visibility that the weather condition has.
28	     * @param brightness The brightness that the weather condition has.
29	     * @param dampness The dampness that the weather condition has.
30	     */
31	    WeatherCond(double visibilty,double brightness,double dampness)
32	    {
33	        weatherAttributes = new HashMap<>();
34	        weatherAttributes.put("visibility", visibilty);
35	        weatherAttributes.put("brightness", brightness);
36	        weatherAttributes.put("dampness", dampness);
37	    }
38	
39	    /**
40	     * Returns the next weather condition based on the current
41	     * weather condition and a random generator.
42	     * @return The next weather condition.
43	     */
44	    public WeatherCond nextCondition()
45	    {
46	        List<WeatherCond> tempList = new ArrayList<>();
47	        if (!timeOfDay.isDay()) {
48	            switch(this) {
49	                case Sunny:
50	                    tempList.add(Cloudy);
51	                    tempList.add(Windy);
52	                    break;
53	                case Rain:
54	                    tempList.add(Storm);
55	                    tempList.add(Cloudy);
56	                    break;
57	                default:
58	                    tempList.add(Fog);
59	                    tempList.add(Rain);
60	                    break;
61	            }
62	        }
63	        else {
64	            switch(this) {
65	                case Sunny:
66	                    tempList.add(Cloudy);
67	                    tempList.add(Windy);
68	                    break;
69	                case Rain:
70	                    tempList.add(Storm);
71	                    tempList.add(Cloudy);
72	                    break;
73	                default:
74	                    tempList.add(Sunny);
75	                    tempList.add(Fog);
76	                    tempList.add(Rain);
77	                    break;
78	            }
79	        }
80	        return tempList.get(rand.nextInt((tempList.size())));
81	    }
82	
83	    /**
84	     * Returns visibility.
85	     * @return visibility.
86	     */
87	    public double getVisibilty()
88	    {
89	        return weatherAttributes.get("visibility");
90	    }
91	
92	    /**
93	     * Returns brightness.
94	     * @return brightness.
95	     */
96	    public double getBrightness()
97	    {
98	        return weatherAttributes.get("brightness");
99	    }
100	    
101	    /**
102	     * Returns dampness.
103	     * @return dampness.
104	     */
105	    public double getDampness()
106	    {
107	        return weatherAttributes.get("dampness");
108	    }
109	    
110	    /**
111	     * Returns the Map of all weather attributes.
112	     * @return The Map of all weather attributes.
113	     */
114	    public Map<String,Double> getWeatherAttributesMap()
115	    {
116	        return weatherAttributes;
117	    }
118	
119	    /**
120	     * Sets the timeOfDay field of the weather condition to reference 
121	     * another Time object
122	     * @param time The time object referencesd
123	     */
124	    public void setTime(Time time)
125	    {
126	        timeOfDay = time;
127	    }
128	}
