143	        }
144	        stats.countFinished();
145	        
146	        for (int x = 0; x < diseases.size(); x++) {
147	            diseaseDisplay = diseaseDisplay + diseases.get(x).getName() + ": " + diseaseCount[x] + " ";
148	        }
