9	    private int row;
10	    private int col;
11	
12	    /**
13	     * Represent a row and column.
14	     * @param row The row.
15	     * @param col The column.
16	     */
17	    public Location(int row, int col)
18	    {
19	        this.row = row;
20	        this.col = col;
21	    }
22	    
23	    /**
24	     * Implement content equality.
25	     */
26	    public boolean equals(Object obj)
27	    {
28	        if(obj instanceof Location) {
29	            Location other = (Location) obj;
30	            return row == other.getRow() && col == other.getCol();
31	        }
32	        else {
33	            return false;
34	        }
35	    }
