25	    private static final Random rand = Randomizer.getRandom();
26	    // String name for the Water fern
27	    public static final String name = "Water_Fern";
28	
29	    /**
30	     * Create Water fern. Water_Fern are created as age zero.
31	     * 
32	     * @param time The time in the simulation.
33	     * @param field The field currently occupied.
34	     * @param location The location within the field.
35	     * @param parentDiseases The diseases the parent of this Water fern had.
36	     */
37	    public Water_Fern(Time time, Field field, Location location, Set<Disease> parentDiseases)
38	    {
39	        super(time, field, location);
40	        canGoLand = false;
41	        canGoWater = true;
42	        age = 0;
43	        for(Disease parentDisease : parentDiseases){
44	            if (parentDisease.isSpreadByBirth()){
45	                setDiseases.add(parentDisease);
46	            }
47	        }
48	    }
49	
50	    /**
51	     * Create Water fern. The Water fern are created with a random age.
52	     * 
53	     * @param time The time in the simulation.
54	     * @param field The field currently occupied.
55	     * @param location The location within the field.
56	     */
57	    public Water_Fern(Time time, Field field, Location location)
58	    {
59	        super(time, field, location);     
60	        canGoLand = false;
61	        canGoWater = true;
62	        age = rand.nextInt(MAX_AGE);
63	        for(Disease disease : Simulator.diseases){
64	            if(disease.getStartingActorsMap().containsKey(name) && rand.nextDouble()<=disease.getStartingActorsMap().get(name)){
65	                setDiseases.add(disease);
66	            }
67	        }
68	    }
69	
70	    /**
71	     * Generate a number representing the number of births,
72	     * if it can breed.
73	     * @return The number of births (may be zero).
74	     */
75	    public int breed()
76	    {
77	        int births = 0;
78	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
79	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
80	        }
81	        return births;
82	    }
83	
84	    /**
85	     * Water_Fern can breed if it has reached the breeding age.
86	     * @return true if the Water fern can breed, false otherwise.
87	     */
88	    private boolean canBreed()
89	    {
90	        return age >= BREEDING_AGE;
91	    }
92	
93	    /**
94	     * Returns the String name.
95	     * @return The String name.
96	     */
97	    public String getActorName (){
98	        return name;
99	    }
100	
101	    /**
102	     * Returns the max age that the Water fern can have before dying.
103	     * @return The max age that the Water fern can have before dying.
104	     */
105	    public int getMaxAge()
106	    {
107	        return MAX_AGE;
108	    }
109	
110	    /**
111	     * Creates new Water fern 
112	     * If the Water fern are created at the start of the simulation no parentDiseases Set is given as there is no parent.
113	     * @param location The new location of the child
114	     * @param Set<Disease> The diseases that the parent had is passed down
115	     * @return The new Water fern created
116	     */
117	    public Plant birth(Location loc, Set<Disease>... parentDiseases)
118	    {
119	        if (parentDiseases.length > 0) {
120	            return new Water_Fern(getTime(), getField(), loc,parentDiseases[0]);
121	        }
122	        return new Water_Fern(getTime(), getField(), loc);
123	    }
124	}
