5	/**
6	 * A class representing shared characteristics of actors.
7	 *
8	 * @version 27.02.22
9	 */
10	public abstract class Actor
11	{
12	    // Whether the actor is alive or not.
13	    private boolean alive;
14	    // The actor's field.
15	    private Field field;
16	    // The actor's position in the field.
17	    private Location location;
18	    //The actor's age
19	    protected int age;
20	    //A reference to the time object of the simulation
21	    private Time time; 
22	    //The diseases that the actor has
23	    protected Set<Disease> setDiseases;
24	    //If the animal can go on water
25	    protected boolean canGoWater;
26	    //If the animal can go on land
27	    protected boolean canGoLand;
28	
29	    /**
30	     * Create a new actor at location in field with time as well.
31	     * With a set that will add any disease that it catches
32	     * 
33	     * @param field The field currently occupied.
34	     * @param location The location within the field.
35	     * @param time The time in the simulation
36	     */
37	    public Actor(Time time, Field field, Location location)
38	    {
39	        alive = true;
40	        this.field = field;
41	        setLocation(location);
42	        this.time = time;
43	        setDiseases = new HashSet();
44	    }
45	
46	    /**
